/* Request objects (RFC 9101) through the C ABI. Keys are generated by the library; the public half comes from authlas_jwk_public. */
#include <stdio.h>
#include <string.h>
#include "authlas.h"

static int failures = 0;
#define CHECK(c, m) do { if (!(c)) { printf("FAIL line %d: %s\n", __LINE__, m); failures++; } } while (0)

static char *text_of(AuthlasBuf *b) {
    static char buf[16384];
    snprintf(buf, sizeof buf, "%.*s", (int)b->len, (const char *)b->data);
    return buf;
}

/* Copies a buffer into a caller-owned string and frees it. */
static void take(AuthlasBuf *b, char *dst, size_t n) {
    snprintf(dst, n, "%s", text_of(b));
    authlas_buf_free(b);
}

static void gen_keys(char *priv, size_t pn, char *pub, size_t un) {
    AuthlasBuf k = { NULL, 0 }, p = { NULL, 0 };
    authlas_jwk_generate_ec("P-256", &k);
    snprintf(priv, pn, "%s", text_of(&k));
    authlas_jwk_public(priv, &p);
    snprintf(pub, un, "%s", text_of(&p));
    authlas_buf_free(&k);
    authlas_buf_free(&p);
}

int main(void) {
    char priv[4096], pub[4096], priv2[4096], pub2[4096];
    gen_keys(priv, sizeof priv, pub, sizeof pub);
    gen_keys(priv2, sizeof priv2, pub2, sizeof pub2);

    const char *client = "app";
    const char *issuer = "https://as.example";
    const char *params =
        "{\"response_type\":\"code\",\"redirect_uri\":\"https://app.example/cb\",\"scope\":\"read\",\"state\":\"xyz\"}";

    AuthlasBuf obj = { NULL, 0 };
    int st = authlas_request_object_build("ES256", priv, client, issuer, params, 300, &obj);
    CHECK(st == AUTHLAS_STATUS_OK && strchr(text_of(&obj), '.') != NULL, "a request object is built and signed");
    char jwt[8192];
    take(&obj, jwt, sizeof jwt);

    const char *algs = "[\"ES256\"]";

    /* A valid object verifies and yields its parameters as a query string. */
    AuthlasBuf q = { NULL, 0 };
    st = authlas_request_object_verify(jwt, pub, algs, client, issuer, 600, 0, 0, &q);
    CHECK(st == AUTHLAS_STATUS_OK && strstr(text_of(&q), "response_type=code") != NULL, "a valid object verifies");
    CHECK(strstr(text_of(&q), "state=xyz") != NULL, "the verified query carries the signed state");
    authlas_buf_free(&q);

    /* Signed by another key: refused. */
    AuthlasBuf wrongkey = { NULL, 0 };
    CHECK(authlas_request_object_verify(jwt, pub2, algs, client, issuer, 600, 0, 0, &wrongkey) != AUTHLAS_STATUS_OK,
          "an object signed by another key is refused");
    authlas_buf_free(&wrongkey);

    /* Wrong audience (issuer): refused. */
    AuthlasBuf wrongaud = { NULL, 0 };
    CHECK(authlas_request_object_verify(jwt, pub, algs, client, "https://other-as.example", 600, 0, 0, &wrongaud) != AUTHLAS_STATUS_OK,
          "an object addressed to another authorization server is refused");
    authlas_buf_free(&wrongaud);

    /* The authenticated client is a different one: refused. */
    AuthlasBuf wrongclient = { NULL, 0 };
    CHECK(authlas_request_object_verify(jwt, pub, algs, "intruder", issuer, 600, 0, 0, &wrongclient) != AUTHLAS_STATUS_OK,
          "an object signed for a different client is refused");
    authlas_buf_free(&wrongclient);

    /* An algorithm outside the allow-list: refused. */
    AuthlasBuf wrongalg = { NULL, 0 };
    CHECK(authlas_request_object_verify(jwt, pub, "[\"PS256\"]", client, issuer, 600, 0, 0, &wrongalg) != AUTHLAS_STATUS_OK,
          "an algorithm outside the allow-list is refused");
    authlas_buf_free(&wrongalg);

    /* Empty allow-list: refused. */
    AuthlasBuf noalg = { NULL, 0 };
    CHECK(authlas_request_object_verify(jwt, pub, "[]", client, issuer, 600, 0, 0, &noalg) != AUTHLAS_STATUS_OK,
          "an empty algorithm list is refused");
    authlas_buf_free(&noalg);

    /* Expired object (the clock is past exp): refused. */
    AuthlasBuf late = { NULL, 0 };
    CHECK(authlas_request_object_verify(jwt, pub, algs, client, issuer, 600, 0, 1ULL << 40, &late) != AUTHLAS_STATUS_OK,
          "an expired object is refused");
    authlas_buf_free(&late);

    /* The lifetime cap: an object that lives longer than max_lifetime is refused. */
    AuthlasBuf longobj = { NULL, 0 };
    authlas_request_object_build("ES256", priv, client, issuer, params, 600, &longobj);
    char long_jwt[8192];
    take(&longobj, long_jwt, sizeof long_jwt);
    AuthlasBuf tiny = { NULL, 0 };
    CHECK(authlas_request_object_verify(long_jwt, pub, algs, client, issuer, 1, 0, 0, &tiny) != AUTHLAS_STATUS_OK,
          "an object whose lifetime exceeds the cap is refused");
    authlas_buf_free(&tiny);

    /* Fingerprint is short and stable; the raw reference is not returned. */
    AuthlasBuf fp = { NULL, 0 };
    CHECK(authlas_request_uri_fingerprint("urn:ietf:params:oauth:request_uri:abc", &fp) == AUTHLAS_STATUS_OK && fp.len == 12,
          "the request_uri fingerprint is 12 characters");
    CHECK(strstr(text_of(&fp), "urn:") == NULL, "the fingerprint does not contain the reference");
    authlas_buf_free(&fp);

    printf(failures ? "%d FAILURES\n" : "request object checks passed\n", failures);
    return failures ? 1 : 0;
}
